// THROWAWAY review correction. Today A / Tasks B chosen; Habits & Calendar retain current host layout.
// No app data copied: every count, completion and source below is synthetic.
const correctionOriginalTaskEditor=taskEditor;
taskEditor=(...args)=>{const v=variant;variant='B';const html=correctionOriginalTaskEditor(...args);variant=v;return html;};
const reviewOriginalBuildHabits=buildHabits;
buildHabits=()=>{const rows=reviewOriginalBuildHabits();const reading=rows.find(h=>h.id==='h2');reading.goal={frequency:'weekly',target:3,kind:'days'};reading.historyGoals=[{effective:reading.start,goal:structuredClone(reading.goal)}];
 rows.push({id:'h4',name:'按时入睡',emoji:'🌙',group:'生活',start:'2026-07-01',goal:{frequency:'daily',target:1,kind:'threshold',threshold:'00:00'},pending:null,inactive:false,coverageStart:'2026-09-14',full:false,historyGoals:[{effective:'2026-07-01',goal:{frequency:'daily',target:1,kind:'threshold',threshold:'00:00'}}],local:['2026-10-05','2026-10-08'],mapped:[]},
 {id:'h5',name:'早间规划',emoji:'🗓',group:'生活',start:'2026-07-01',goal:{frequency:'weekly',target:3,kind:'days'},pending:null,inactive:false,coverageStart:'2026-07-01',full:true,historyGoals:[{effective:'2026-07-01',goal:{frequency:'weekly',target:3,kind:'days'}}],local:['2026-10-05','2026-10-07'],mapped:[]},
 {id:'h6',name:'睡前回顾',emoji:'📝',group:'生活',start:'2026-07-01',goal:{frequency:'weekly',target:3,kind:'days'},pending:null,inactive:false,coverageStart:'2026-09-14',full:false,historyGoals:[{effective:'2026-07-01',goal:{frequency:'weekly',target:3,kind:'days'}}],local:['2026-10-05','2026-10-06','2026-10-07'],mapped:[]});return rows;};
habits=buildHabits();habitSelected=null;let overviewExpanded=new Set(),habitOverviewScroll=0,collaborationCandidate=refineVariants[params.get('variant')]?params.get('variant'):'A';
function knownWeekCount(h){return habitStats(h).currentWeek}
function recentHabitCells(h){const s=habitStats(h),first=addDays(demoDate,-6);return `<div class="habit-recent-cells">${Array.from({length:7},(_,i)=>{const date=addDays(first,i),on=s.attained.includes(date);return `<button type="button" class="habit-cell ${on?'known-complete':''} ${date===demoDate?'is-today':''}" data-habit-day="${date}" data-habit-id="${h.id}" title="${date} · ${on?'合成达标证据':'未知，不能推断未完成'}">${['日','一','二','三','四','五','六'][dateObj(date).getUTCDay()]}${on?'<span>●</span>':''}</button>`}).join('')}</div>`;}
function overviewHabitRow(h){const s=habitStats(h),on=s.attained.includes(demoDate),threshold=h.goal.kind==='threshold';return `<article class="habit-snapshot-row" data-context-habit="${h.id}"><div class="habit-snapshot-identity"><strong>${esc(h.name)}</strong><p>${goalLabel(h.goal)} · ${h.full?'完整合成历史':'有限合成覆盖'}</p><small>来源：${h.mapped.length?'本地完成、映射外部样例':'本地完成样例'}</small></div><div class="habit-snapshot-value"><strong>${threshold?'实际时刻未知':h.goal.frequency==='weekly'?s.currentWeek+' / '+h.goal.target:on?'已达标':'未知'}</strong><small>今天：${on?'已知达标':'未知'}</small></div><div class="habit-completion-control"><input type="checkbox" data-overview-check="${h.id}" aria-label="记录 ${esc(h.name)} 今天达标" ${h.local.includes(demoDate)?'checked':''} ${h.start>demoDate?'disabled':''}><small>${on?'已有完成证据':'无完成证据'}</small></div><div class="habit-recent"><span>过去 7 天</span>${recentHabitCells(h)}</div><button class="habit-expand" data-overview-expand="${h.id}" aria-expanded="${overviewExpanded.has(h.id)}">${overviewExpanded.has(h.id)?'收起':'展开'}</button>${overviewExpanded.has(h.id)?`<section class="overview-history"><div class="section-title"><b>近期合成历史</b><button class="text-button" data-select-habit="${h.id}">查看详细统计 ↗</button></div><p>${h.coverageStart}–${demoDate} · ${h.full?'完整合成覆盖':'全历史累计与最高连续未知'}</p><div class="overview-history-cells">${Array.from({length:28},(_,i)=>{const d=addDays(demoDate,i-27);return `<button data-habit-day="${d}" data-habit-id="${h.id}" ${d<h.coverageStart||d<h.start?'disabled':''} class="${s.attained.includes(d)?'attained':''}" title="${d}">${d.slice(8)}${s.attained.includes(d)?' ●':''}</button>`}).join('')}</div></section>`:''}</article>`;}
function summaryHabitRow(h){const s=habitStats(h);return `<button class="habits-summary-row ${h.id===habitSelected?'selected':''}" data-select-habit="${h.id}" data-context-habit="${h.id}"><span>${esc(h.name)}${h.inactive?' · 停用':''}</span><strong>${h.goal.frequency==='weekly'?s.currentWeek+' / '+h.goal.target:s.attained.includes(demoDate)?'达标':'未知'}</strong><small>${goalLabel(h.goal)}${h.pending?' · 有待生效目标':''}</small></button>`;}
function habitualOverview(){const current=habits.filter(h=>!h.inactive),daily=current.filter(h=>h.goal.kind==='threshold'),completion=current.filter(h=>h.goal.kind!=='threshold');return `<section class="habits-today-detail current-habit-overview"><div class="habits-group-heading"><div><p class="section-label">今日情况</p><h3>已知与未知并列</h3></div><small>${demoDate}</small></div><section class="habits-target-section"><div class="habits-target-heading"><h4>每日锚点</h4><small>目标 / 明确实际</small></div>${daily.map(overviewHabitRow).join('')}</section><section class="habits-target-section"><div class="habits-target-heading"><h4>本周习惯在今天</h4><small>达标天数 · 今日状态</small></div>${completion.map(overviewHabitRow).join('')}</section></section>`;}
habitsPage=()=>{const visible=habits.filter(h=>showInactive||!h.inactive),weekly=visible.filter(h=>h.goal.frequency==='weekly'&&!h.inactive),daily=visible.filter(h=>h.goal.frequency==='daily'&&!h.inactive),h=habits.find(h=>h.id===habitSelected),total=weekly.reduce((sum,h)=>sum+knownWeekCount(h),0),target=weekly.reduce((sum,h)=>sum+h.goal.target,0);return header('本周习惯','保留现有本周摘要与今日列表 · 合成样例',`<button class="btn" id="inactive-habits">${showInactive?'收起停用':'查看停用'}</button><button class="btn primary" id="new-habit" aria-label="新增习惯">＋</button>`)+`<div class="current-habits-host habits-layout"><aside class="habits-week-summary"><div class="habits-group-heading"><div><p class="section-label">本周统计</p><h3>简短摘要</h3></div><small>周一至周日</small></div><div class="habits-summary-total"><strong>${total} / ${target}</strong><span>已知达标天数 / 目标天数</span></div>${weekly.map(summaryHabitRow).join('')}${daily.length?`<h4 class="summary-anchor-label">每日锚点</h4>${daily.map(summaryHabitRow).join('')}`:''}${showInactive&&habits.some(h=>h.inactive)?`<h4 class="summary-anchor-label">停用 · 保留历史</h4>${habits.filter(h=>h.inactive).map(summaryHabitRow).join('')}`:''}<p class="summary-coverage">点击左侧习惯查看详细统计。覆盖不足时，已知计数是下界，未知不代表未完成。</p><dl class="habits-provenance"><div><dt>更新时间</dt><dd>合成样例 · ${demoDate}</dd></div><div><dt>来源</dt><dd>内存样例，未读取真实 Vault</dd></div></dl></aside>${h?`<section class="chosen-habit-detail"><div class="detail-return"><button class="text-button" id="habit-overview-return">← 回到今日习惯</button><span class="tiny muted">从左侧 ${esc(h.name)} 打开</span></div><div class="habit-detail">${habitDetail(h)}</div></section>`:habitualOverview()}</div>`;};
// Calendar has one host layout: month + date review, then same-date Task list below.
const originalMonthMarkup=monthMarkup;
recordPreview=()=>{const n=selectedDay,status=dayStatus(n),plan=n===10?plans.map(p=>`<li><b>${refinePlanLabel(p)} · ${esc(p.name)}</b><p>${esc(p.note)}</p></li>`).join(''):status==='reviewed'?'<li>早间留出阅读和活动时间。</li>':'',review=status==='reviewed'?'这个合成日期已有晚间复盘。':n===10?'阅读 25 分钟、桌面整理完成。晚间复盘未填写。':'未建立 Daily Record。';return `<aside class="calendar-summary current-calendar-review"><div class="calendar-selected-heading"><div><p class="section-label">选中日期</p><h3>10 月 ${n} 日</h3></div><span class="calendar-summary-status">${status==='reviewed'?'有复盘':status==='unreviewed'?'无复盘':'无记录'}</span></div><div class="calendar-summary-copy"><strong>${status==='reviewed'?'晚间复盘':'日期回顾'}</strong><p>${review}</p>${plan?`<h4>当天计划</h4><ol>${plan}</ol>`:''}</div><button class="btn" id="open-full-today">打开完整 Today ↗</button></aside>`;};
calendarPage=()=>{const items=tasks.filter(t=>t.date===dateFor(selectedDay));return header('日历','回看月份，右侧预览选定日；下方是当天任务',`<label class="holiday-toggle"><input id="holidays" type="checkbox" ${holidayVisible?'checked':''}>中 / 美节日样例</label><button class="btn primary" id="calendar-add" aria-label="新增所选日期任务">＋</button>`)+`<section class="current-calendar-host"><div class="current-calendar-frame"><section class="calendar-month-region"><div class="calendar-month-heading"><div><p class="section-label">月视图 · 月历</p><h3>2026 年 10 月</h3></div><div class="calendar-legend"><span><i data-calendar-marker="reviewed"></i>有复盘</span><span><i data-calendar-marker="unreviewed"></i>无复盘</span><span>空白：无记录</span></div></div><div class="refine-month current-month-grid">${originalMonthMarkup()}</div></section>${recordPreview()}</div><section class="calendar-task-panel current-calendar-tasks"><div class="section-title"><div><p class="section-label">选中日期 · 任务</p><h3>10 月 ${selectedDay} 日的任务</h3></div><small>${items.length} 项</small></div>${items.length?pendingRows(items):'<p class="muted">这一天还没有任务。</p>'}</section></section>`;};
const correctionOriginalBind=bind;
bind=()=>{correctionOriginalBind();$('#habit-overview-return')?.addEventListener('click',()=>{habitSelected=null;render()});document.querySelectorAll('[data-select-habit]').forEach(b=>b.onclick=()=>{habitOverviewScroll=$('.current-habits-host')?.scrollTop||0;habitSelected=b.dataset.selectHabit;render()});document.querySelectorAll('[data-overview-expand]').forEach(b=>b.onclick=()=>{const id=b.dataset.overviewExpand;overviewExpanded.has(id)?overviewExpanded.delete(id):overviewExpanded.add(id);render()});document.querySelectorAll('[data-overview-check]').forEach(b=>b.onchange=()=>{const h=habits.find(h=>h.id===b.dataset.overviewCheck);if(b.checked){if(!h.local.includes(demoDate))h.local.push(demoDate)}else h.local=h.local.filter(d=>d!==demoDate);render();notify(h.mapped.includes(demoDate)?'本地完成已更新；外部证据仍独立保留':'本地达标记录已更新')});document.querySelectorAll('[data-toggle-habit]').forEach(b=>b.onclick=()=>{const h=habits.find(h=>h.id===b.dataset.toggleHabit);h.inactive=!h.inactive;if(h.inactive)habitSelected=null;render();notify(h.inactive?'Habit 已停用，历史与统计保留':'Habit 已恢复')});document.querySelectorAll('[data-discuss]').forEach(b=>b.onclick=()=>action('discuss:'+b.dataset.discuss));document.querySelectorAll('[data-task-more]').forEach(b=>b.onclick=e=>openMore(b.dataset.taskMore,e));};
const correctionOriginalRender=render;
render=()=>{if(page==='today')variant='A';else if(page==='tasks')variant='B';else if(page==='habits'||page==='calendar')variant='A';else collaborationCandidate=variant;correctionOriginalRender();const fixed=page!=='collaboration';$('#previous').hidden=fixed;$('#next').hidden=fixed;const labels={today:['Today · A 已选','紧凑概览 · 就近浮窗'],tasks:['Tasks · B 已选','Content 优先 · 属性在下方'],habits:['Habits · 主界面保留','点左侧习惯后才展开详细统计'],calendar:['Calendar · 现有结构','只演示新增与任务详情浮窗']};if(fixed){$('#variant-name').textContent=labels[page][0];$('#variant-description').textContent=labels[page][1]}else{$('#variant-name').textContent='协作待选 · '+variant;$('#variant-description').textContent=refineVariants[variant][1]}if(page==='habits'||page==='calendar'){const u=new URL(location);u.searchParams.set('variant','current');history.replaceState(null,'',u)}if(page==='habits'&&!habitSelected&&$('.current-habits-host'))$('.current-habits-host').scrollTop=habitOverviewScroll;};
const correctionNavigate=navigate;
navigate=next=>{if(next==='habits'&&page!=='habits')habitSelected=null;if(next==='collaboration')variant=collaborationCandidate;correctionNavigate(next)};
const correctionReset=$('#reset').onclick;
$('#reset').onclick=()=>{correctionReset();habitSelected=null;overviewExpanded.clear();habitOverviewScroll=0;render()};
const correctionCycle=cycle;
cycle=direction=>{if(page==='collaboration')correctionCycle(direction)};
render();
const correctionInspect=$('#inspect').onclick;
$('#inspect').onclick=()=>{correctionInspect();const pre=$('#state-dialog pre'),state=JSON.parse(pre.textContent);state.presentation={today:'A chosen',tasks:'B chosen',habits:'current overview, detail on selection',calendar:'current host layout, no variant selection',collaboration:'unselected '+collaborationCandidate};state.habitSelected=habitSelected;state.habitOverview=habitSelected==null;pre.textContent=JSON.stringify(state,null,2);};
